"Certificate not found",certNotFoundText:"No certificate matches the code {code}. Please check it.",certTitle:"Certificate of achievement",certAwardedTo:"This certificate is awarded to",certForCompleting:"for successfully completing the course",certDetail:"{hours} hours of training · final quiz score: {score}%",trainer:"Trainer",issuedOn:"Issued on",verifyAt:"Verifiable on Cirta Academy",certCode:"Certificate code",verify:"Verify",verifyTitle:"Verify a certificate",verifyLead:"Enter the code printed at the bottom of the certificate to confirm it was issued by Cirta Academy.",teacherTitle:"Teacher space",teacherLead:"Hello {name}, here's how your courses are going.",newCourse:"New course",kpiStudents:"Students",kpiAvgProgress:"Average progress",kpiAtRisk:"Need a nudge",weeklySignups:"Sign-ups per week",last8Weeks:"Last 8 weeks",thisWeek:"This wk",recentQuizzes:"Latest quizzes",nothingYet:"Nothing yet.",myCoursesTeacher:"My courses",course:"Course",completion:"Certified",manage:"Manage",atRiskTitle:"Students who need a nudge",atRiskHint:"No activity for 10 days or more",lastSeen:"seen {when}",remind:"Remind",noAtRisk:"Everyone is active. 🎉",courseManageLead:"{n} student(s) enrolled.",publicPage:"Public page",tab_students:"Students",tab_content:"Lessons & quiz",tab_settings:"Details",searchStudent:"Search a student",status:"Status",allStatuses:"All statuses",student:"Student",progress:"Progress",bestQuiz:"Best quiz",lastActivityCol:"Last activity",attempts:"{n} attempt(s)","status_on-track":"On track","status_at-risk":"Needs a nudge",status_completed:"Certified",lessonFunnel:"Progress by lesson",funnelHint:"How many students finished each lesson: spot where they drop off.",courseInfo:"Details",titleIn:"Title ({lang})",summaryIn:"Summary ({lang})",format:"Format",priceDA:"Price (DA)",hours:"Hours",seats:"Seats",startDate:"Start date",days:"Days",time:"Time",color:"Color",outcomes:"Outcomes (one per line)",outcomesHint:"E.g. Write simple JavaScript",lessons:"Lessons",add